"""Reference-aware VCF reading, normalization and writing.

Public API:

- :class:`VcfHeader` — the ``##`` meta-information lines (kept verbatim
  and in order) together with the sample names declared by the single
  ``#CHROM`` column header.
- :class:`VcfRecord` — one VCF data row: the eight fixed columns, an
  optional ``FORMAT`` column and the per-sample text columns.
- :class:`VcfFile` — a parsed VCF document pairing a header with its
  records.
- :func:`read_vcf` — parse VCF text from a path or text stream.
- :func:`normalize_record` / :func:`normalize_vcf` — trim common
  allele suffixes/prefixes and left-align indels against a reference.
- :func:`render_vcf` / :func:`write_vcf` — serialize a VCF document
  with tabs and ``"\\n"``.

Ordinary sequence alleles only contain the IUPAC DNA symbols
``ACGTRYSWKMBDHVN`` (lower-case input is upper-cased).  Records carrying
symbolic (``<...>``), break-end (brackets or a ``.`` join), spanning
(``*``) or missing (``.``) ALT alleles are validated against the
reference but never trimmed or shifted.
"""

from __future__ import annotations

import io
import os
from collections.abc import Iterable, Mapping, Sequence
from dataclasses import dataclass, replace

from .sequence_io import SequenceRecord, _VALID_BASES

__all__ = [
    "VcfHeader",
    "VcfRecord",
    "VcfFile",
    "VcfFormatError",
    "ReferenceMismatchError",
    "read_vcf",
    "normalize_record",
    "normalize_vcf",
    "render_vcf",
    "write_vcf",
]

_FIXED_COLUMNS = ("#CHROM", "POS", "ID", "REF", "ALT", "QUAL", "FILTER", "INFO")
_MIN_COLUMNS = 8


class VcfFormatError(ValueError):
    """Malformed VCF input (missing/duplicate header, bad columns or fields)."""


class ReferenceMismatchError(ValueError):
    """A record's CHROM is absent/duplicated in the reference or REF disagrees."""


@dataclass(frozen=True)
class VcfHeader:
    """The VCF header.

    ``meta_lines`` holds the ``##`` meta-information lines verbatim,
    without their line terminators and in input order.  ``samples``
    holds the sample names taken from the single ``#CHROM`` header line
    (an empty tuple for sample-less VCF).
    """

    meta_lines: tuple[str, ...] = ()
    samples: tuple[str, ...] = ()

    @property
    def column_names(self) -> tuple[str, ...]:
        """All column names as declared by the ``#CHROM`` line."""
        if self.samples:
            return _FIXED_COLUMNS + ("FORMAT",) + self.samples
        return _FIXED_COLUMNS


@dataclass(frozen=True)
class VcfRecord:
    """One VCF data row.

    The fixed columns are ``chrom``, ``pos`` (1-based), ``id``, ``ref``,
    ``alt`` (a tuple of ALT allele strings), ``qual``, ``filter`` and
    ``info``.  For a VCF with samples, ``format_text`` holds the FORMAT
    string and ``sample_text`` one verbatim column per sample; both are
    empty for sample-less VCF.  ``line_number`` is the 1-based source
    line of a parsed record (``0`` for records built directly).
    """

    chrom: str
    pos: int
    id: str
    ref: str
    alt: tuple[str, ...]
    qual: str
    filter: str
    info: str
    format_text: str | None = None
    sample_text: tuple[str, ...] = ()
    line_number: int = 0

    @property
    def alt_text(self) -> str:
        """The ALT column as it appears on disk."""
        return ",".join(self.alt)


@dataclass(frozen=True)
class VcfFile:
    """A parsed VCF document: a header and its records in input order.

    ``source`` is the path or stream label the document was read from
    and is used to qualify error messages during normalization.
    """

    header: VcfHeader
    records: tuple[VcfRecord, ...] = ()
    source: str = ""


def _line_error(source: str, line_number: int, message: str) -> VcfFormatError:
    return VcfFormatError(f"{source}:{line_number}: {message}")


def _is_plain_allele(allele: str) -> bool:
    """Whether *allele* is an ordinary sequence allele of real bases.

    The gVCF spanning value ``*``, the missing value ``.``, symbolic
    alleles (``<DEL>``) and break-end alleles (``]chr:123]N``, ``N.``)
    are not plain.
    """
    if not allele or allele == "*" or allele == ".":
        return False
    if "<" in allele or ">" in allele:
        return False
    if "[" in allele or "]" in allele or "." in allele or "*" in allele:
        return False
    return True


def _validate_allele(allele: str) -> str:
    """Upper-case and validate one ordinary sequence allele."""
    upper = allele.upper()
    for offset, symbol in enumerate(upper):
        if symbol not in _VALID_BASES:
            raise ValueError(
                f"invalid allele symbol {symbol!r} at offset {offset} of {allele!r}"
            )
    return upper


def _parse_pos(pos_text: str, source: str, number: int) -> int:
    if not pos_text or any(char < "0" or char > "9" for char in pos_text):
        raise _line_error(
            source, number, f"POS {pos_text!r} is not a positive integer"
        )
    pos = int(pos_text)
    if pos <= 0:
        raise _line_error(
            source, number, f"POS {pos_text!r} is not a positive integer"
        )
    return pos


def _parse_record_line(
    line: str, number: int, source: str, samples: Sequence[str]
) -> VcfRecord:
    fields = line.split("\t")
    if len(fields) < _MIN_COLUMNS:
        raise _line_error(
            source,
            number,
            f"expected at least 8 tab-separated columns, got {len(fields)}",
        )
    if samples:
        expected = _MIN_COLUMNS + 1 + len(samples)
        if len(fields) != expected:
            raise _line_error(
                source,
                number,
                f"expected {expected} columns to match the #CHROM header, got {len(fields)}",
            )
        format_text = fields[8]
        if not format_text:
            raise _line_error(source, number, "empty FORMAT column")
        sample_text = tuple(fields[9:])
    else:
        if len(fields) != _MIN_COLUMNS:
            raise _line_error(
                source,
                number,
                f"expected 8 columns to match the sample-less #CHROM header, "
                f"got {len(fields)}",
            )
        format_text = None
        sample_text = ()

    chrom, pos_text, ident, ref_text, alt_text, qual, flt, info = fields[:8]

    if not chrom:
        raise _line_error(source, number, "empty CHROM column")
    pos = _parse_pos(pos_text, source, number)

    if not ref_text:
        raise _line_error(source, number, "empty REF allele")
    try:
        ref = _validate_allele(ref_text)
    except ValueError as exc:
        raise _line_error(source, number, str(exc)) from None

    if not alt_text:
        raise _line_error(source, number, "empty ALT column")
    alts: list[str] = []
    for allele in alt_text.split(","):
        if allele == "":
            raise _line_error(source, number, "empty ALT allele")
        if not _is_plain_allele(allele):
            alts.append(allele)
            continue
        try:
            alts.append(_validate_allele(allele))
        except ValueError as exc:
            raise _line_error(source, number, str(exc)) from None

    return VcfRecord(
        chrom=chrom,
        pos=pos,
        id=ident,
        ref=ref,
        alt=tuple(alts),
        qual=qual,
        filter=flt,
        info=info,
        format_text=format_text,
        sample_text=sample_text,
        line_number=number,
    )


def _parse_header_line(
    line: str, number: int, source: str
) -> tuple[str, ...]:
    """Validate the ``#CHROM`` line and return its sample names."""
    columns = line.split("\t")
    if tuple(columns[:8]) != _FIXED_COLUMNS:
        raise _line_error(
            source,
            number,
            "the first eight #CHROM header columns must be exactly "
            "#CHROM\\tPOS\\tID\\tREF\\tALT\\tQUAL\\tFILTER\\tINFO",
        )
    tail = columns[8:]
    if not tail:
        return ()
    if tail[0] != "FORMAT":
        raise _line_error(
            source, number, "the ninth column, when present, must be FORMAT"
        )
    samples = tuple(tail[1:])
    if not samples:
        raise _line_error(source, number, "FORMAT column requires at least one sample")
    if any(not sample for sample in samples):
        raise _line_error(source, number, "empty sample name in #CHROM header")
    return samples


def read_vcf(
    source: "str | os.PathLike[str] | io.TextIOBase",
) -> VcfFile:
    """Read and validate a whole VCF document from *source*.

    *source* is either a filesystem path (``str`` or :class:`os.PathLike`)
    or an already-open text stream.  ``##`` meta-information lines are
    kept verbatim and in order; exactly one legal ``#CHROM`` line is
    required and every data row must match its columns.  Records are
    returned in input order.

    Raises :class:`VcfFormatError` for malformed input and :class:`OSError`
    when opening a path fails.
    """
    if isinstance(source, io.IOBase):
        stream: io.TextIOBase = source
        source_name = getattr(stream, "name", None)
        if not isinstance(source_name, str) or not source_name:
            source_name = "<stream>"
        close = False
    elif isinstance(source, (str, os.PathLike)):
        path = os.fspath(source)
        stream = open(path, "r", encoding="utf-8", newline="")
        source_name = path
        close = True
    else:
        raise TypeError("source must be a text path or a text stream")

    try:
        meta_lines: list[str] = []
        samples: tuple[str, ...] | None = None
        records: list[VcfRecord] = []

        for number, raw_line in enumerate(stream, start=1):
            line = raw_line.rstrip("\r\n")
            if line.startswith("##"):
                if samples is not None:
                    raise _line_error(
                        source_name,
                        number,
                        "meta-information line after the #CHROM header",
                    )
                meta_lines.append(line)
            elif line.startswith("#"):
                if samples is not None:
                    raise _line_error(
                        source_name, number, "duplicate #CHROM column header"
                    )
                samples = _parse_header_line(line, number, source_name)
            else:
                if samples is None:
                    raise _line_error(
                        source_name, number, "data row before the #CHROM column header"
                    )
                records.append(
                    _parse_record_line(line, number, source_name, samples)
                )

        if samples is None:
            raise VcfFormatError(
                f"{source_name}:1: missing #CHROM column header"
            )
        return VcfFile(
            VcfHeader(tuple(meta_lines), samples), tuple(records), source_name
        )
    finally:
        if close:
            stream.close()


def _build_reference(
    reference: Iterable[SequenceRecord],
) -> tuple[dict[str, str], set[str]]:
    """Map CHROM to sequence, tracking identifiers appearing more than once."""
    sequences: dict[str, str] = {}
    duplicates: set[str] = set()
    for record in reference:
        if record.identifier in sequences:
            duplicates.add(record.identifier)
        else:
            sequences[record.identifier] = record.sequence
    return sequences, duplicates


def _record_error(source: str, record: VcfRecord, message: str) -> VcfFormatError:
    if source and record.line_number:
        return VcfFormatError(f"{source}:{record.line_number}: {message}")
    if record.line_number:
        return VcfFormatError(f"line {record.line_number}: {message}")
    return VcfFormatError(message)


def _resolve_chromosome(
    record: VcfRecord,
    sequences: Mapping[str, str],
    duplicates: set[str],
) -> str:
    if record.chrom in duplicates:
        raise ReferenceMismatchError(
            f"CHROM {record.chrom} POS {record.pos}: CHROM occurs more than once "
            "in the reference"
        )
    try:
        return sequences[record.chrom]
    except KeyError:
        raise ReferenceMismatchError(
            f"CHROM {record.chrom} POS {record.pos}: no matching record in the reference"
        ) from None


def _minimize(
    pos: int, ref: str, alts: Sequence[str]
) -> tuple[int, str, tuple[str, ...]]:
    """Remove the common suffix and prefix shared by all alleles.

    At least one base is always retained per allele and *pos* (1-based)
    is advanced by the number of stripped leading bases.
    """
    # Common suffix: compare each ALT against REF up to the shorter
    # length, always leaving at least one base per allele.
    suffix = 0
    while True:
        index = len(ref) - 1 - suffix
        if index <= 0:
            break
        ref_base = ref[index]
        ok = True
        for alt in alts:
            alt_index = len(alt) - 1 - suffix
            if alt_index <= 0 or alt[alt_index] != ref_base:
                ok = False
                break
        if not ok:
            break
        suffix += 1
    if suffix:
        ref = ref[: len(ref) - suffix]
        alts = tuple(alt[: len(alt) - suffix] for alt in alts)

    # Common prefix: at least one base must remain in every allele.
    prefix = 0
    shortest = min(len(ref), min(len(alt) for alt in alts))
    while prefix < shortest - 1 and all(
        alt[prefix] == ref[prefix] for alt in alts
    ):
        prefix += 1
    if prefix:
        ref = ref[prefix:]
        alts = tuple(alt[prefix:] for alt in alts)
        pos += prefix

    return pos, ref, tuple(alts)


def _lengths_differ(ref: str, alts: Sequence[str]) -> bool:
    return any(len(alt) != len(ref) for alt in alts)


def _normalize_against(
    record: VcfRecord,
    sequences: Mapping[str, str],
    duplicates: set[str],
    source: str,
) -> VcfRecord:
    chromosome = _resolve_chromosome(record, sequences, duplicates)

    end = record.pos - 1 + len(record.ref)
    if record.pos < 1 or end > len(chromosome):
        raise _record_error(
            source,
            record,
            f"CHROM {record.chrom} POS {record.pos}: REF of length {len(record.ref)} "
            f"is out of bounds for a reference of length {len(chromosome)}",
        )

    expected = chromosome[record.pos - 1 : end].upper()
    if expected != record.ref:
        raise ReferenceMismatchError(
            f"CHROM {record.chrom} POS {record.pos}: REF does not match the "
            f"reference: expected {expected!r}, found {record.ref!r}"
        )

    if not all(_is_plain_allele(allele) for allele in record.alt):
        # Symbolic, break-end, spanning or missing ALT: verify only.
        return record

    pos, ref, alts = _minimize(record.pos, record.ref, record.alt)

    # Left-align: prepend the preceding reference base to every allele
    # and re-minimize.  A move only happens when re-minimization removes
    # a (different) right-hand base, i.e. the extended window represents
    # the same haplotypes; once a step leaves the alleles unchanged the
    # minimum POS has been reached.
    while pos > 1 and _lengths_differ(ref, alts):
        preceding = chromosome[pos - 2].upper()
        next_pos, next_ref, next_alts = _minimize(
            pos - 1,
            preceding + ref,
            tuple(preceding + alt for alt in alts),
        )
        if (next_pos, next_ref, next_alts) == (pos, ref, alts):
            break
        pos, ref, alts = next_pos, next_ref, next_alts

    return replace(record, pos=pos, ref=ref, alt=alts)


def normalize_record(
    record: VcfRecord,
    reference: "Mapping[str, str] | Iterable[SequenceRecord]",
) -> VcfRecord:
    """Normalize one record against *reference*.

    *reference* is either a mapping of CHROM to upper-case reference
    sequence or an iterable of :class:`~genome_variant.sequence_io.SequenceRecord`
    (duplicate identifiers raise :class:`ReferenceMismatchError`).

    The REF fragment at POS is always verified.  Records whose ALT
    contains a symbolic, break-end, spanning (``*``) or missing (``.``)
    allele are returned unchanged.  Otherwise all sequence alleles are
    trimmed of their shared suffix and prefix (one base is always kept)
    and, when allele lengths differ, left-shifted across repeated
    reference bases to the smallest POS representing the same
    haplotypes, re-minimizing after every shift.  ID, QUAL, FILTER,
    INFO, FORMAT, sample text and ALT order are preserved.

    Raises :class:`ReferenceMismatchError` for an absent/duplicate CHROM
    or a REF that disagrees with the reference, and
    :class:`VcfFormatError` for a record that runs past the reference.
    """
    if isinstance(reference, Mapping):
        sequences = dict(reference)
        duplicates: set[str] = set()
    else:
        sequences, duplicates = _build_reference(reference)
    return _normalize_against(record, sequences, duplicates, "")


def normalize_vcf(
    document: VcfFile,
    reference: "Mapping[str, str] | Iterable[SequenceRecord]",
) -> VcfFile:
    """Normalize every record of *document* against *reference*.

    Record order is preserved; see :func:`normalize_record` for the
    per-record rules.  Every record is validated before the normalized
    document is returned, so an error never comes with partial output.
    """
    if isinstance(reference, Mapping):
        sequences = dict(reference)
        duplicates: set[str] = set()
    else:
        sequences, duplicates = _build_reference(reference)

    normalized = tuple(
        _normalize_against(record, sequences, duplicates, document.source)
        for record in document.records
    )
    return VcfFile(document.header, normalized, document.source)


def _record_line(record: VcfRecord) -> str:
    fields = [
        record.chrom,
        str(record.pos),
        record.id,
        record.ref,
        record.alt_text,
        record.qual,
        record.filter,
        record.info,
    ]
    if record.format_text is not None:
        fields.append(record.format_text)
        fields.extend(record.sample_text)
    return "\t".join(fields)


def render_vcf(document: VcfFile) -> str:
    """Serialize *document* to VCF text.

    Output uses tabs and ``"\\n"`` line endings and always ends with
    exactly one trailing newline; a record-less VCF still writes the
    complete header (``##`` lines followed by the ``#CHROM`` line).
    """
    lines = list(document.header.meta_lines)
    lines.append("\t".join(document.header.column_names))
    lines.extend(_record_line(record) for record in document.records)
    return "\n".join(lines) + "\n"


def write_vcf(
    document: VcfFile,
    output: "str | os.PathLike[str] | io.TextIOBase",
) -> None:
    """Write *document* to *output* as VCF text.

    Tabs and ``"\\n"`` are used throughout with exactly one trailing
    newline; an empty-record VCF still writes the complete header.
    """
    text = render_vcf(document)
    if isinstance(output, io.IOBase):
        output.write(text)
    elif isinstance(output, (str, os.PathLike)):
        with open(os.fspath(output), "w", encoding="utf-8", newline="") as stream:
            stream.write(text)
    else:
        raise TypeError("output must be a text path or a text stream")

"""FASTA/FASTQ reading and normalization.

Public API:

- :class:`SequenceRecord` — one sequence with identifier, description and
  optional per-base quality values.
- :func:`read_sequences` — lazily read records from a text path or text
  stream; the format is ``"fasta"``, ``"fastq"`` or ``"auto"``.
- :func:`write_sequences` — write records in FASTA or FASTQ form.

Sequences only contain the IUPAC DNA symbols ``ACGTRYSWKMBDHVN``.  FASTQ
quality values use the Phred+33 encoding with ASCII characters 33–126.
"""

from __future__ import annotations

import io
import os
from collections.abc import Iterable, Iterator
from dataclasses import dataclass

__all__ = [
    "SequenceRecord",
    "SequenceFormatError",
    "SequenceValidationError",
    "read_sequences",
    "write_sequences",
]

_VALID_BASES = frozenset("ACGTRYSWKMBDHVN")
_INPUT_FORMATS = ("fasta", "fastq", "auto")
_OUTPUT_FORMATS = ("fasta", "fastq")


class SequenceFormatError(ValueError):
    """Malformed FASTA/FASTQ input (structure, identifiers, lengths)."""


class SequenceValidationError(ValueError):
    """A sequence contains a symbol outside the allowed IUPAC set."""


@dataclass(frozen=True)
class SequenceRecord:
    """A single sequence record.

    ``identifier`` is the first whitespace-delimited field of the title
    line; ``description`` holds the remainder (``""`` when absent).
    ``quality`` is ``None`` for FASTA records and a tuple of Phred scores
    for FASTQ records.
    """

    identifier: str
    sequence: str
    description: str = ""
    quality: tuple[int, ...] | None = None


def _clean_sequence(raw: str) -> str:
    """Strip in-line whitespace and upper-case a raw sequence fragment."""
    return "".join(raw.split()).upper()


def _validate_sequence(identifier: str, sequence: str) -> None:
    for position, symbol in enumerate(sequence, start=1):
        if symbol not in _VALID_BASES:
            raise SequenceValidationError(
                f"record {identifier!r}: invalid symbol {symbol!r} at position {position}"
            )


def _split_title(title: str, source: str, line_number: int) -> tuple[str, str]:
    fields = title.split(None, 1)
    if not fields:
        raise SequenceFormatError(f"{source}:{line_number}: empty sequence identifier")
    identifier = fields[0]
    description = fields[1] if len(fields) == 2 else ""
    return identifier, description


def _line_error(source: str, line_number: int, message: str) -> SequenceFormatError:
    return SequenceFormatError(f"{source}:{line_number}: {message}")


def _fasta_records(
    lines: Iterator[tuple[int, str]], source: str
) -> Iterator[SequenceRecord]:
    header_line: str | None = None
    header_number = 0
    seq_parts: list[str] = []

    for number, raw_line in lines:
        line = raw_line.rstrip("\r\n")
        if line.startswith(">"):
            if header_line is not None:
                yield _finish_fasta(header_line, header_number, seq_parts, source)
            header_line = line
            header_number = number
            seq_parts = []
        elif line.strip():
            if header_line is None:
                raise _line_error(
                    source,
                    number,
                    "content before first title line (expected a line starting with '>')",
                )
            seq_parts.append(line)
        # Blank lines outside or inside a record are ignored.

    if header_line is not None:
        yield _finish_fasta(header_line, header_number, seq_parts, source)


def _finish_fasta(
    header_line: str, header_number: int, parts: list[str], source: str
) -> SequenceRecord:
    identifier, description = _split_title(header_line[1:], source, header_number)
    sequence = _clean_sequence("".join(parts))
    if not sequence:
        raise _line_error(source, header_number, "empty sequence")
    _validate_sequence(identifier, sequence)
    return SequenceRecord(identifier, sequence, description)


def _check_quality_segment(segment: str, source: str, line_number: int) -> None:
    for char in segment:
        value = ord(char)
        if value < 33 or value > 126:
            raise _line_error(
                source,
                line_number,
                f"quality character {char!r} is outside the ASCII 33-126 range",
            )


def _fastq_records(
    lines: Iterator[tuple[int, str]], source: str
) -> Iterator[SequenceRecord]:
    # State machine over logical lines.  Sequence and quality may each
    # span several physical lines; record boundaries are determined by the
    # '+' separator and the number of quality characters matching the
    # sequence length.
    header_line: str | None = None
    header_number = 0
    seq_parts: list[str] = []
    qual_segments: list[str] = []
    in_quality = False

    for number, raw_line in lines:
        line = raw_line.rstrip("\r\n")

        if header_line is None:
            if not line:
                raise _line_error(
                    source,
                    number,
                    "incomplete FASTQ record (expected a title line starting with '@')",
                )
            if not line.startswith("@"):
                raise _line_error(
                    source, number, "expected a FASTQ title line starting with '@'"
                )
            header_line = line
            header_number = number
            seq_parts = []
            qual_segments = []
            in_quality = False
            continue

        if not in_quality:
            if line.startswith("+"):
                plus_title = line[1:]
                if plus_title and plus_title != header_line[1:]:
                    raise _line_error(
                        source,
                        number,
                        "FASTQ separator title does not match the record title",
                    )
                if not _clean_sequence("".join(seq_parts)):
                    raise _line_error(source, header_number, "empty sequence")
                in_quality = True
            else:
                if not line.strip():
                    raise _line_error(source, number, "empty sequence")
                seq_parts.append(line)
            continue

        if not line:
            raise _line_error(source, number, "incomplete FASTQ record (missing quality values)")
        _check_quality_segment(line, source, number)
        qual_segments.append(line)

        sequence = _clean_sequence("".join(seq_parts))
        quality_text = "".join(qual_segments)
        if len(quality_text) > len(sequence):
            raise _line_error(
                source,
                number,
                f"quality length {len(quality_text)} does not match sequence length {len(sequence)}",
            )
        if len(quality_text) == len(sequence):
            yield _finish_fastq(
                header_line, header_number, sequence, quality_text, source
            )
            header_line = None

    if header_line is not None:
        raise _line_error(source, header_number, "incomplete FASTQ record")


def _finish_fastq(
    header_line: str,
    header_number: int,
    sequence: str,
    quality_text: str,
    source: str,
) -> SequenceRecord:
    identifier, description = _split_title(header_line[1:], source, header_number)
    if not sequence:
        raise _line_error(source, header_number, "empty sequence")
    _validate_sequence(identifier, sequence)
    if len(quality_text) != len(sequence):
        raise _line_error(
            source,
            header_number,
            f"quality length {len(quality_text)} does not match sequence length {len(sequence)}",
        )
    quality = tuple(ord(char) - 33 for char in quality_text)
    return SequenceRecord(identifier, sequence, description, quality)


def _enumerate_lines(stream: Iterable[str]) -> Iterator[tuple[int, str]]:
    for number, line in enumerate(stream, start=1):
        yield number, line


def read_sequences(
    source: "str | os.PathLike[str] | io.TextIOBase",
    format: str = "auto",
) -> Iterator[SequenceRecord]:
    """Lazily read sequence records from *source*.

    *source* is either a filesystem path (``str`` or :class:`os.PathLike`)
    or an already-open text stream.  *format* is ``"fasta"``, ``"fastq"``
    or ``"auto"``; with ``"auto"`` the format is detected from the first
    non-empty line (``>`` → FASTA, ``@`` → FASTQ).

    Records are produced in input order.  Errors raised while opening a
    path propagate as :class:`OSError`; malformed input raises
    :class:`SequenceFormatError` or :class:`SequenceValidationError`
    during iteration and are never swallowed.
    """
    if format not in _INPUT_FORMATS:
        raise ValueError(
            f"unsupported format {format!r}; expected one of {', '.join(_INPUT_FORMATS)}"
        )

    if isinstance(source, io.IOBase):
        stream: io.TextIOBase = source
        source_name = getattr(stream, "name", None)
        if not isinstance(source_name, str) or not source_name:
            source_name = "<stream>"
        close = False
    elif isinstance(source, (str, os.PathLike)):
        path = os.fspath(source)
        stream = open(path, "r", encoding="utf-8", newline="")
        source_name = path
        close = True
    else:
        raise TypeError("source must be a text path or a text stream")

    try:
        yield from _read_from_stream(stream, source_name, format)
    finally:
        if close:
            stream.close()


def _read_from_stream(
    stream: Iterable[str], source_name: str, format: str
) -> Iterator[SequenceRecord]:
    numbered = _enumerate_lines(stream)

    first_number = 0
    first_line: str | None = None
    for number, raw_line in numbered:
        candidate = raw_line.rstrip("\r\n")
        if candidate.strip():
            first_number = number
            first_line = candidate
            break

    if first_line is None:
        if format == "auto":
            raise SequenceFormatError(
                f"{source_name}: empty input; cannot determine format"
            )
        raise SequenceFormatError(f"{source_name}: empty input")

    if format == "auto":
        if first_line.startswith(">"):
            detected = "fasta"
        elif first_line.startswith("@"):
            detected = "fastq"
        else:
            raise _line_error(
                source_name,
                first_number,
                "cannot determine format: first non-empty line must start with '>' or '@'",
            )
    else:
        detected = format

    def replay() -> Iterator[tuple[int, str]]:
        yield first_number, first_line + "\n"
        yield from numbered

    # The per-format parsers reject a first line that lacks their title
    # marker themselves (reported as content before / unexpected title).
    if detected == "fasta":
        yield from _fasta_records(replay(), source_name)
    else:
        yield from _fastq_records(replay(), source_name)


def write_sequences(
    records: Iterable[SequenceRecord],
    output: "str | os.PathLike[str] | io.TextIOBase",
    format: str = "fasta",
    line_width: int = 60,
) -> None:
    """Write *records* to *output* in FASTA or FASTQ form.

    FASTA sequences are wrapped at *line_width* characters (a positive
    integer); FASTQ always uses the fixed four-line layout regardless of
    *line_width*.  Records without quality values cannot be written as
    FASTQ.  Output uses ``"\\n"`` line endings and ends with exactly one
    trailing newline.
    """
    if format not in _OUTPUT_FORMATS:
        raise ValueError(f"unsupported format {format!r}; expected 'fasta' or 'fastq'")
    if not isinstance(line_width, int) or isinstance(line_width, bool) or line_width <= 0:
        raise ValueError("line_width must be a positive integer")

    if isinstance(output, io.IOBase):
        stream: io.TextIOBase = output
        close = False
    elif isinstance(output, (str, os.PathLike)):
        stream = open(os.fspath(output), "w", encoding="utf-8", newline="")
        close = True
    else:
        raise TypeError("output must be a text path or a text stream")

    try:
        for record in records:
            _validate_sequence(record.identifier, record.sequence)
            if format == "fasta":
                stream.write(_format_fasta_record(record, line_width))
            else:
                stream.write(_format_fastq_record(record))
    finally:
        if close:
            stream.close()


def _format_title(record: SequenceRecord) -> str:
    if record.description:
        return record.identifier + " " + record.description
    return record.identifier


def _format_fasta_record(record: SequenceRecord, line_width: int) -> str:
    parts = [">" + _format_title(record) + "\n"]
    sequence = record.sequence
    for start in range(0, len(sequence), line_width):
        parts.append(sequence[start : start + line_width])
        parts.append("\n")
    return "".join(parts)


def _format_fastq_record(record: SequenceRecord) -> str:
    if record.quality is None:
        raise ValueError(
            f"record {record.identifier!r} has no quality values; cannot write it as FASTQ"
        )
    if len(record.quality) != len(record.sequence):
        raise ValueError(
            f"record {record.identifier!r}: quality length does not match sequence length"
        )
    quality_chars = []
    for value in record.quality:
        if not 0 <= value <= 93:
            raise ValueError(
                f"record {record.identifier!r}: quality score {value} is outside the "
                "Phred+33 range 0-93"
            )
        quality_chars.append(chr(value + 33))
    title = _format_title(record)
    return f"@{title}\n{record.sequence}\n+{title}\n{''.join(quality_chars)}\n"

input.content:
"""GFF3-driven variant annotation for parsed VCF documents.

Public API:

- :class:`AnnotationFormatError` — malformed GFF3 input (bad CDS rows,
  coordinates or phase, missing Parent, a strand other than ``+``/``-``,
  CDS fragments spanning several sequences or contradictory reading
  frames) or a VCF that already declares or uses the ``GVANN`` key.
- :func:`annotate_vcf` — add one ``GVANN`` INFO item per ALT allele to
  every record of a :class:`~genome_variant.vcf.VcfFile`.

CDS features are grouped by their GFF3 ``Parent`` attribute into
transcripts.  The standard genetic code is used; only ``A``/``C``/``G``/``T``
single-base substitutions inside a CDS are annotated with a coding
consequence.  Every other ALT (indels, ambiguous or symbolic alleles)
receives ``UNSUPPORTED``/``MODIFIER`` and records without a CDS hit
receive ``NON_CODING``/``MODIFIER``.
"""

from __future__ import annotations

import io
import os
from collections import defaultdict
from collections.abc import Iterable
from dataclasses import dataclass, replace

from .sequence_io import SequenceRecord
from .vcf import VcfFile, VcfHeader, VcfRecord

__all__ = [
    "AnnotationFormatError",
    "annotate_vcf",
]

GVANN_ID = "GVANN"

#: GFF3 column 3 type that delimits the annotation ranges.
_CDS_TYPE = "CDS"

#: Standard genetic code, codons read on the coding strand.
_GENETIC_CODE = {
    "TTT": "F", "TTC": "F", "TTA": "L", "TTG": "L",
    "CTT": "L", "CTC": "L", "CTA": "L", "CTG": "L",
    "ATT": "I", "ATC": "I", "ATA": "I", "ATG": "M",
    "GTT": "V", "GTC": "V", "GTA": "V", "GTG": "V",
    "TCT": "S", "TCC": "S", "TCA": "S", "TCG": "S",
    "CCT": "P", "CCC": "P", "CCA": "P", "CCG": "P",
    "ACT": "T", "ACC": "T", "ACA": "T", "ACG": "T",
    "GCT": "A", "GCC": "A", "GCA": "A", "GCG": "A",
    "TAT": "Y", "TAC": "Y", "TAA": "*", "TAG": "*",
    "CAT": "H", "CAC": "H", "CAA": "Q", "CAG": "Q",
    "AAT": "N", "AAC": "N", "AAA": "K", "AAG": "K",
    "GAT": "D", "GAC": "D", "GAA": "E", "GAG": "E",
    "TGT": "C", "TGC": "C", "TGA": "*", "TGG": "W",
    "CGT": "R", "CGC": "R", "CGA": "R", "CGG": "R",
    "AGT": "S", "AGC": "S", "AGA": "R", "AGG": "R",
    "GGT": "G", "GGC": "G", "GGA": "G", "GGG": "G",
}

_COMPLEMENT = str.maketrans("ACGT", "TGCA")

#: Consequence key ordered from most to least severe; the impact each
#: consequence maps to follows the same order.
_CONSEQUENCE_IMPACT = {
    "START_LOST": "HIGH",
    "STOP_GAINED": "HIGH",
    "STOP_LOST": "HIGH",
    "SYNONYMOUS": "LOW",
    "MISSENSE": "MODERATE",
}


class AnnotationFormatError(ValueError):
    """Malformed GFF3 data or a VCF that already carries ``GVANN``."""


@dataclass(frozen=True)
class _CdsFragment:
    """One CDS GFF3 row: 1-based inclusive interval on one sequence."""

    seqid: str
    start: int
    end: int
    strand: str
    phase: int
    line_number: int


@dataclass(frozen=True)
class _Transcript:
    """A Parent group assembled into coding-strand codons."""

    parent: str
    strand: str
    sequence: str
    # Each entry: (coding position, 0-based index into sequence) for the
    # coding bases in coding order.  Indexing the reference this way (and
    # reverse-complementing the read for a minus-strand transcript) yields
    # the coding sequence codon by codon.
    layout: tuple[tuple[int, int], ...]


def _gff_error(source: str, line_number: int, message: str) -> AnnotationFormatError:
    return AnnotationFormatError(f"{source}:{line_number}: {message}")


def _decode_gff3(text: str) -> str:
    """Decode one percent-encoded GFF3 attribute value component."""
    output: list[str] = []
    index = 0
    while index < len(text):
        char = text[index]
        if char == "%":
            if index + 2 >= len(text):
                raise ValueError("truncated percent escape")
            try:
                output.append(chr(int(text[index + 1 : index + 3], 16)))
            except ValueError:
                raise ValueError(f"invalid percent escape {text[index:index + 3]!r}")
            index += 3
        else:
            output.append(char)
            index += 1
    return "".join(output)


def _parse_attributes(
    column: str, source: str, line_number: int
) -> dict[str, list[str]]:
    """Parse the GFF3 column 9 into tag -> decoded values in column order."""
    attributes: dict[str, list[str]] = {}
    if column == "":
        return attributes
    for assignment in column.split(";"):
        if not assignment:
            raise _gff_error(source, line_number, "empty GFF3 attribute assignment")
        if "=" not in assignment:
            raise _gff_error(
                source, line_number, f"GFF3 attribute {assignment!r} lacks '='"
            )
        tag, raw_values = assignment.split("=", 1)
        if not tag:
            raise _gff_error(source, line_number, "empty GFF3 attribute tag")
        values: list[str] = []
        for raw_value in raw_values.split(","):
            try:
                values.append(_decode_gff3(raw_value))
            except ValueError as exc:
                raise _gff_error(
                    source,
                    line_number,
                    f"GFF3 attribute {tag!r}: {exc}",
                ) from None
        attributes.setdefault(tag, []).extend(values)
    return attributes


def _parse_cds_fragments(
    stream: Iterable[str], source: str
) -> dict[str, list[_CdsFragment]]:
    """Read a GFF3 stream and collect CDS fragments keyed by Parent."""
    fragments: dict[str, list[_CdsFragment]] = defaultdict(list)
    for line_number, raw_line in enumerate(stream, start=1):
        line = raw_line.rstrip("\r\n")
        if not line or line.startswith("#"):
            continue
        columns = line.split("\t")
        if len(columns) != 9:
            raise _gff_error(
                source,
                line_number,
                f"expected 9 tab-separated GFF3 columns, got {len(columns)}",
            )
        if columns[2] != _CDS_TYPE:
            continue

        seqid, _source_type, _type, start_text, end_text, _score, strand, phase_text, attributes_text = columns

        if not seqid:
            raise _gff_error(source, line_number, "CDS feature has an empty seqid")
        try:
            start = int(start_text)
        except ValueError:
            raise _gff_error(
                source,
                line_number,
                f"CDS start {start_text!r} is not an integer",
            ) from None
        try:
            end = int(end_text)
        except ValueError:
            raise _gff_error(
                source, line_number, f"CDS end {end_text!r} is not an integer"
            ) from None
        if start < 1 or end < 1:
            raise _gff_error(
                source,
                line_number,
                f"CDS coordinates {start}-{end} are not 1-based positive",
            )
        if start > end:
            raise _gff_error(
                source,
                line_number,
                f"CDS start {start} is greater than its end {end}",
            )
        if strand not in ("+", "-"):
            raise _gff_error(
                source,
                line_number,
                f"CDS strand {strand!r} is not '+' or '-'",
            )
        if phase_text not in ("0", "1", "2"):
            raise _gff_error(
                source,
                line_number,
                f"CDS phase {phase_text!r} is not one of '0', '1', '2'",
            )

        attributes = _parse_attributes(attributes_text, source, line_number)
        parents = attributes.get("Parent")
        if not parents:
            raise _gff_error(
                source, line_number, "CDS feature is missing a Parent attribute"
            )
        if any(parent == "" for parent in parents):
            raise _gff_error(
                source, line_number, "CDS feature has an empty Parent value"
            )
        phase = int(phase_text)
        for parent in parents:
            fragments[parent].append(
                _CdsFragment(
                    seqid=seqid,
                    start=start,
                    end=end,
                    strand=strand,
                    phase=phase,
                    line_number=line_number,
                )
            )
    return fragments


def _build_layout(
    parent: str, fragments: list[_CdsFragment], source: str
) -> _Transcript:
    """Order CDS fragments into coding bases and validate reading frames."""
    first = fragments[0]
    for fragment in fragments[1:]:
        if fragment.seqid != first.seqid:
            raise _gff_error(
                source,
                fragment.line_number,
                f"CDS for Parent {parent!r} spans multiple sequences "
                f"({first.seqid!r} and {fragment.seqid!r})",
            ) from None
    if False:  # pragma: no cover - placeholder kept out of the raise chain
        raise _gff_error(source, first.line_number, "")

    strand = first.strand
    sorted_fragments = sorted(fragments, key=lambda fragment: fragment.start)

    # On the minus strand the coding order runs from the largest genomic
    # coordinate downwards; every fragment is also read in reverse.
    if strand == "+":
        ordered = sorted_fragments
    else:
        ordered = list(reversed(sorted_fragments))

    layout: list[tuple[int, int]] = []
    coding_position = 1

    def add_interval(fragment: _CdsFragment, length: int, reverse: bool) -> None:
        nonlocal coding_position
        for offset in range(length):
            genomic_offset = length - 1 - offset if reverse else offset
            layout.append((coding_position, fragment.start - 1 + genomic_offset))
            coding_position += 1

    # Translate each fragment's declared phase into the number of coding
    # bases missing from the 5' side of this fragment relative to codon
    # boundaries, then demand the assembled layout agrees.
    consumed = 0
    for fragment in ordered:
        if strand == "+":
            length = fragment.end - fragment.start + 1
            add_interval(fragment, length, reverse=False)
            expected_phase = (3 - (consumed % 3)) % 3
            if fragment.phase != expected_phase:
                raise _gff_error(
                    source,
                    fragment.line_number,
                    f"CDS phase {fragment.phase} for Parent {parent!r} contradicts "
                    f"the assembled reading frame (expected {expected_phase})",
                )
            consumed += length
        else:
            length = fragment.end - fragment.start + 1
            add_interval(fragment, length, reverse=True)
            # Phase counts bases missing at the fragment's 5' end, which on
            # the minus strand is its higher-coordinate edge: after reading
            # this (reversed) fragment the number of coding bases already
            # seen fixes the phase the next fragment must declare.
            expected_phase = (3 - (consumed % 3)) % 3
            if fragment.phase != expected_phase:
                raise _gff_error(
                    source,
                    fragment.line_number,
                    f"CDS phase {fragment.phase} for Parent {parent!r} contradicts "
                    f"the assembled reading frame (expected {expected_phase})",
                )
            consumed += length

    return _Transcript(
        parent=parent,
        strand=strand,
        sequence=first.seqid,
        sequence=tuple(layout),
    )


def _build_transcripts(
    fragments: dict[str, list[_CdsFragment]], source: str
) -> tuple[_Transcript, ...]:
    transcripts = [
        _build_layout(parent, parent_fragments, source)
        for parent, parent_fragments in fragments.items()
    ]
    transcripts.sort(key=lambda transcript: transcript.parent)
    return tuple(transcripts)


def _read_gff3(source: "str | os.PathLike[str] | io.TextIOBase") -> tuple[tuple[_Transcript, ...], str]:
    if isinstance(source, io.IOBase):
        stream: io.TextIOBase = source
        source_name = getattr(stream, "name", None)
        if not isinstance(source_name, str) or not source_name:
            source_name = "<stream>"
        close = False
    elif isinstance(source, (str, os.PathLike)):
        path = os.fspath(source)
        stream = open(path, "r", encoding="utf-8", newline="")
        source_name = path
        close = True
    else:
        raise TypeError("source must be a text path or a text stream")

    try:
        fragments = _parse_cds_fragments(stream, source_name)
        return _build_transcripts(fragments, source_name), source_name
    finally:
        if close:
            stream.close()


def _index_reference(
    reference: Iterable[SequenceRecord],
) -> dict[str, str]:
    sequences: dict[str, str] = {}
    for record in reference:
        sequences[record.identifier] = record.sequence
    return sequences


def _coding_base(transcript: _Transcript, chromosome: str, index: int) -> str:
    base = chromosome[index]
    if transcript.strand == "-":
        base = base.translate(_COMPLEMENT)
    return base


def _codons(
    transcript: _Transcript, chromosome: str
) -> list[tuple[int, tuple[int, ...], str]]:
    """Yield ``(codon_number, genomic_indices, codon_bases)`` per full codon."""
    codon_list: list[tuple[int, tuple[int, ...], str]] = []
    layout = transcript.layout
    for codon_number, start in enumerate(range(0, len(layout) - 2, 3), start=1):
        positions = layout[start : start + 3]
        indices = tuple(index for _coding_pos, index in positions)
        bases = "".join(_coding_base(transcript, chromosome, index) for index in indices)
        codon_list.append((codon_number, indices, bases))
    return codon_list


def _classify(
    codon_number: int, old_codon: str, new_codon: str
) -> tuple[str, str]:
    old_aa = _GENETIC_CODE[old_codon]
    new_aa = _GENETIC_CODE[new_codon]
    if codon_number == 1 and old_aa == "M" and new_aa != "M":
        consequence = "START_LOST"
    elif old_aa != "*" and new_aa == "*":
        consequence = "STOP_GAINED"
    elif old_aa == "*" and new_aa != "*":
        consequence = "STOP_LOST"
    elif old_aa == new_aa:
        consequence = "SYNONYMOUS"
    else:
        consequence = "MISSENSE"
    return consequence, _CONSEQUENCE_IMPACT[consequence]


def _is_snv(ref: str, alt: str) -> bool:
    return len(ref) == 1 and len(alt) == 1 and ref in "ACGT" and alt in "ACGT" and ref != alt


def _annotate_alt(
    record: VcfRecord,
    alt: str,
    transcripts: tuple[_Transcript, ...],
    sequences: dict[str, str],
) -> str:
    if not _is_snv(record.ref, alt):
        return f"{alt}|UNSUPPORTED|MODIFIER|.|.|.|."

    genomic_index = record.pos - 1
    hits: list[_Transcript] = [
        transcript
        for transcript in transcripts
        if transcript.sequence == record.chrom
        and any(index == genomic_index for _pos, index in transcript.layout)
    ]

    if not hits:
        return f"{alt}|NON_CODING|MODIFIER|.|.|.|."

    items: list[str] = []
    for transcript in hits:
        chromosome = sequences[record.chrom]
        for codon_number, indices, old_codon in _codons(transcript, chromosome):
            if genomic_index not in indices:
                continue
            position_in_codon = indices.index(genomic_index)
            alt_coding_base = (
                alt.translate(_COMPLEMENT) if transcript.strand == "-" else alt
            )
            new_bases = list(old_codon)
            new_bases[position_in_codon] = alt_coding_base
            new_codon = "".join(new_bases)

            layout = transcript.layout
            coding_positions = {
                index: coding_pos for coding_pos, index in layout
            }
            cds_pos = coding_positions[genomic_index]

            consequence, impact = _classify(codon_number, old_codon, new_codon)
            old_aa = _GENETIC_CODE[old_codon]
            new_aa = _GENETIC_CODE[new_codon]
            items.append(
                "|".join(
                    (
                        alt,
                        consequence,
                        impact,
                        transcript.parent,
                        str(cds_pos),
                        f"{old_codon}>{new_codon}",
                        f"{old_aa}>{new_aa}",
                    )
                )
            )
            break
    if not items:
        # The base belongs to the transcript's CDS span but fell outside a
        # complete codon (frame data inconsistent in length); treat the
        # coordinate as non-coding rather than guessing.
        return f"{alt}|NON_CODING|MODIFIER|.|.|.|."
    return ",".join(items)


def _info_keys(info: str) -> list[str]:
    keys: list[str] = []
    for item in info.split(";"):
        key = item.split("=", 1)[0]
        keys.append(key)
    return keys


def _check_existing_gvann(document: VcfFile) -> None:
    for line in document.header.meta_lines:
        if line.startswith(f"##{GVANN_ID}=") or line.startswith(
            f"##{GVANN_ID}<"
        ):
            raise AnnotationFormatError(
                f"{GVANN_ID} is already declared in the VCF header"
            )
    for record in document.records:
        if record.info and GVANN_ID in _info_keys(record.info):
            source = document.source
            location = (
                f"{source}:{record.line_number}: "
                if source and record.line_number
                else ""
            )
            raise AnnotationFormatError(
                f"{location}{GVANN_ID} is already present in a VCF record"
            )


_GVANN_HEADER = (
    '##INFO=<ID=GVANN,Number=.,Type=String,Description="Genome variant '
    'annotation: ALT|CONSEQUENCE|IMPACT|TRANSCRIPT|CDS_POS|CODON_CHANGE|'
    'AA_CHANGE; multiple transcripts are comma separated">'
)


def annotate_vcf(
    document: VcfFile,
    reference: "Mapping[str, str] | Iterable[SequenceRecord]",
    features: "str | os.PathLike[str] | io.TextIOBase | tuple[_Transcript, ...]",
) -> VcfFile:
    """Annotate every ALT allele of *document* with a ``GVANN`` INFO item.

    *reference* is a mapping of CHROM to upper-case sequence or an
    iterable of :class:`~genome_variant.sequence_io.SequenceRecord`;
    *features* is a GFF3 text path or text stream (CDS features define
    the annotated ranges, grouped into transcripts by ``Parent``).

    Record order, ALT order, sample columns and every existing field are
    preserved; only a single unique ``##INFO`` declaration for ``GVANN``
    is appended to the meta-information and a ``GVANN`` item is appended
    to the end of each record's INFO column (or starts the column when
    INFO was missing).  Consequences are ``START_LOST``, ``STOP_GAINED``,
    ``STOP_LOST``, ``SYNONYMOUS`` and ``MISSENSE`` for coding single-base
    ``A``/``C``/``G``/``T`` substitutions; SNVs outside every CDS get
    ``NON_CODING``/``MODIFIER`` and non-SNV, ambiguous or symbolic ALTs
    get ``UNSUPPORTED``/``MODIFIER``.

    Raises :class:`AnnotationFormatError` for malformed GFF3 data or a
    document that already declares or uses ``GVANN``, and
    :class:`~genome_variant.vcf.ReferenceMismatchError` when a coding
    record's CHROM is absent/duplicated in the reference or its REF does
    not match.
    """
    if isinstance(features, tuple):
        transcripts = features
    else:
        transcripts, _source_name = _read_gff3(features)

    _check_existing_gvann(document)

    if isinstance(reference, dict) or hasattr(reference, "keys"):
        sequences = dict(reference)
        duplicates: set[str] = set()
    else:
        sequences_map: dict[str, str] = {}
        duplicates = set()
        for record in reference:
            if record.identifier in sequences_map:
                duplicates.add(record.identifier)
            else:
                sequences_map[record.identifier] = record.sequence
        sequences = sequences_map

    from .vcf import ReferenceMismatchError

    annotated_records: list[VcfRecord] = []
    for record in document.records:
        # Reference validation follows normalize_vcf semantics for every
        # record so REF mismatches surface even outside CDS ranges.
        if record.chrom in duplicates:
            raise ReferenceMismatchError(
                f"CHROM {record.chrom} POS {record.pos}: CHROM occurs more than "
                "once in the reference"
            )
        try:
            chromosome = sequences[record.chrom]
        except KeyError:
            raise ReferenceMismatchError(
                f"CHROM {record.chrom} POS {record.pos}: no matching record in "
                "the reference"
            ) from None
        end = record.pos - 1 + len(record.ref)
        if record.pos < 1 or end > len(chromosome):
            from .vcf import VcfFormatError

            source = document.source
            location = (
                f"{source}:{record.line_number}: "
                if source and record.line_number
                else ""
            )
            raise VcfFormatError(
                f"{location}CHROM {record.chrom} POS {record.pos}: REF of length "
                f"{len(record.ref)} is out of bounds for a reference of length "
                f"{len(chromosome)}"
            )
        expected = chromosome[record.pos - 1 : end].upper()
        if expected != record.ref:
            raise ReferenceMismatchError(
                f"CHROM {record.chrom} POS {record.pos}: REF does not match the "
                f"reference: expected {expected!r}, found {record.ref!r}"
            )

        items = [
            _annotate_alt(record, alt, transcripts, sequences)
            for alt in record.alt
        ]
        gvann = f"{GVANN_ID}=" + ",".join(items)
        info = f"{record.info};{gvann}" if record.info else gvann
        annotated_records.append(replace(record, info=info))

    header = VcfHeader(
        meta_lines=document.header.meta_lines + (_GVANN_HEADER,),
        samples=document.header.samples,
    )
    return VcfFile(header, tuple(annotated_records), document.source)

toolUseResult.content:
"""GFF3-driven variant annotation for parsed VCF documents.

Public API:

- :class:`AnnotationFormatError` — malformed GFF3 input (bad CDS rows,
  coordinates or phase, missing Parent, a strand other than ``+``/``-``,
  CDS fragments spanning several sequences or contradictory reading
  frames) or a VCF that already declares or uses the ``GVANN`` key.
- :func:`annotate_vcf` — add one ``GVANN`` INFO item per ALT allele to
  every record of a :class:`~genome_variant.vcf.VcfFile`.

CDS features are grouped by their GFF3 ``Parent`` attribute into
transcripts.  The standard genetic code is used; only ``A``/``C``/``G``/``T``
single-base substitutions inside a CDS are annotated with a coding
consequence.  Every other ALT (indels, ambiguous or symbolic alleles)
receives ``UNSUPPORTED``/``MODIFIER`` and records without a CDS hit
receive ``NON_CODING``/``MODIFIER``.
"""

from __future__ import annotations

import io
import os
from collections import defaultdict
from collections.abc import Iterable
from dataclasses import dataclass, replace

from .sequence_io import SequenceRecord
from .vcf import VcfFile, VcfHeader, VcfRecord

__all__ = [
    "AnnotationFormatError",
    "annotate_vcf",
]

GVANN_ID = "GVANN"

#: GFF3 column 3 type that delimits the annotation ranges.
_CDS_TYPE = "CDS"

#: Standard genetic code, codons read on the coding strand.
_GENETIC_CODE = {
    "TTT": "F", "TTC": "F", "TTA": "L", "TTG": "L",
    "CTT": "L", "CTC": "L", "CTA": "L", "CTG": "L",
    "ATT": "I", "ATC": "I", "ATA": "I", "ATG": "M",
    "GTT": "V", "GTC": "V", "GTA": "V", "GTG": "V",
    "TCT": "S", "TCC": "S", "TCA": "S", "TCG": "S",
    "CCT": "P", "CCC": "P", "CCA": "P", "CCG": "P",
    "ACT": "T", "ACC": "T", "ACA": "T", "ACG": "T",
    "GCT": "A", "GCC": "A", "GCA": "A", "GCG": "A",
    "TAT": "Y", "TAC": "Y", "TAA": "*", "TAG": "*",
    "CAT": "H", "CAC": "H", "CAA": "Q", "CAG": "Q",
    "AAT": "N", "AAC": "N", "AAA": "K", "AAG": "K",
    "GAT": "D", "GAC": "D", "GAA": "E", "GAG": "E",
    "TGT": "C", "TGC": "C", "TGA": "*", "TGG": "W",
    "CGT": "R", "CGC": "R", "CGA": "R", "CGG": "R",
    "AGT": "S", "AGC": "S", "AGA": "R", "AGG": "R",
    "GGT": "G", "GGC": "G", "GGA": "G", "GGG": "G",
}

_COMPLEMENT = str.maketrans("ACGT", "TGCA")

#: Consequence key ordered from most to least severe; the impact each
#: consequence maps to follows the same order.
_CONSEQUENCE_IMPACT = {
    "START_LOST": "HIGH",
    "STOP_GAINED": "HIGH",
    "STOP_LOST": "HIGH",
    "SYNONYMOUS": "LOW",
    "MISSENSE": "MODERATE",
}


class AnnotationFormatError(ValueError):
    """Malformed GFF3 data or a VCF that already carries ``GVANN``."""


@dataclass(frozen=True)
class _CdsFragment:
    """One CDS GFF3 row: 1-based inclusive interval on one sequence."""

    seqid: str
    start: int
    end: int
    strand: str
    phase: int
    line_number: int


@dataclass(frozen=True)
class _Transcript:
    """A Parent group assembled into coding-strand codons."""

    parent: str
    strand: str
    sequence: str
    # Each entry: (coding position, 0-based index into sequence) for the
    # coding bases in coding order.  Indexing the reference this way (and
    # reverse-complementing the read for a minus-strand transcript) yields
    # the coding sequence codon by codon.
    layout: tuple[tuple[int, int], ...]


def _gff_error(source: str, line_number: int, message: str) -> AnnotationFormatError:
    return AnnotationFormatError(f"{source}:{line_number}: {message}")


def _decode_gff3(text: str) -> str:
    """Decode one percent-encoded GFF3 attribute value component."""
    output: list[str] = []
    index = 0
    while index < len(text):
        char = text[index]
        if char == "%":
            if index + 2 >= len(text):
                raise ValueError("truncated percent escape")
            try:
                output.append(chr(int(text[index + 1 : index + 3], 16)))
            except ValueError:
                raise ValueError(f"invalid percent escape {text[index:index + 3]!r}")
            index += 3
        else:
            output.append(char)
            index += 1
    return "".join(output)


def _parse_attributes(
    column: str, source: str, line_number: int
) -> dict[str, list[str]]:
    """Parse the GFF3 column 9 into tag -> decoded values in column order."""
    attributes: dict[str, list[str]] = {}
    if column == "":
        return attributes
    for assignment in column.split(";"):
        if not assignment:
            raise _gff_error(source, line_number, "empty GFF3 attribute assignment")
        if "=" not in assignment:
            raise _gff_error(
                source, line_number, f"GFF3 attribute {assignment!r} lacks '='"
            )
        tag, raw_values = assignment.split("=", 1)
        if not tag:
            raise _gff_error(source, line_number, "empty GFF3 attribute tag")
        values: list[str] = []
        for raw_value in raw_values.split(","):
            try:
                values.append(_decode_gff3(raw_value))
            except ValueError as exc:
                raise _gff_error(
                    source,
                    line_number,
                    f"GFF3 attribute {tag!r}: {exc}",
                ) from None
        attributes.setdefault(tag, []).extend(values)
    return attributes


def _parse_cds_fragments(
    stream: Iterable[str], source: str
) -> dict[str, list[_CdsFragment]]:
    """Read a GFF3 stream and collect CDS fragments keyed by Parent."""
    fragments: dict[str, list[_CdsFragment]] = defaultdict(list)
    for line_number, raw_line in enumerate(stream, start=1):
        line = raw_line.rstrip("\r\n")
        if not line or line.startswith("#"):
            continue
        columns = line.split("\t")
        if len(columns) != 9:
            raise _gff_error(
                source,
                line_number,
                f"expected 9 tab-separated GFF3 columns, got {len(columns)}",
            )
        if columns[2] != _CDS_TYPE:
            continue

        seqid, _source_type, _type, start_text, end_text, _score, strand, phase_text, attributes_text = columns

        if not seqid:
            raise _gff_error(source, line_number, "CDS feature has an empty seqid")
        try:
            start = int(start_text)
        except ValueError:
            raise _gff_error(
                source,
                line_number,
                f"CDS start {start_text!r} is not an integer",
            ) from None
        try:
            end = int(end_text)
        except ValueError:
            raise _gff_error(
                source, line_number, f"CDS end {end_text!r} is not an integer"
            ) from None
        if start < 1 or end < 1:
            raise _gff_error(
                source,
                line_number,
                f"CDS coordinates {start}-{end} are not 1-based positive",
            )
        if start > end:
            raise _gff_error(
                source,
                line_number,
                f"CDS start {start} is greater than its end {end}",
            )
        if strand not in ("+", "-"):
            raise _gff_error(
                source,
                line_number,
                f"CDS strand {strand!r} is not '+' or '-'",
            )
        if phase_text not in ("0", "1", "2"):
            raise _gff_error(
                source,
                line_number,
                f"CDS phase {phase_text!r} is not one of '0', '1', '2'",
            )

        attributes = _parse_attributes(attributes_text, source, line_number)
        parents = attributes.get("Parent")
        if not parents:
            raise _gff_error(
                source, line_number, "CDS feature is missing a Parent attribute"
            )
        if any(parent == "" for parent in parents):
            raise _gff_error(
                source, line_number, "CDS feature has an empty Parent value"
            )
        phase = int(phase_text)
        for parent in parents:
            fragments[parent].append(
                _CdsFragment(
                    seqid=seqid,
                    start=start,
                    end=end,
                    strand=strand,
                    phase=phase,
                    line_number=line_number,
                )
            )
    return fragments


def _build_layout(
    parent: str, fragments: list[_CdsFragment], source: str
) -> _Transcript:
    """Order CDS fragments into coding bases and validate reading frames."""
    first = fragments[0]
    for fragment in fragments[1:]:
        if fragment.seqid != first.seqid:
            raise _gff_error(
                source,
                fragment.line_number,
                f"CDS for Parent {parent!r} spans multiple sequences "
                f"({first.seqid!r} and {fragment.seqid!r})",
            ) from None
    if False:  # pragma: no cover - placeholder kept out of the raise chain
        raise _gff_error(source, first.line_number, "")

    strand = first.strand
    sorted_fragments = sorted(fragments, key=lambda fragment: fragment.start)

    # On the minus strand the coding order runs from the largest genomic
    # coordinate downwards; every fragment is also read in reverse.
    if strand == "+":
        ordered = sorted_fragments
    else:
        ordered = list(reversed(sorted_fragments))

    layout: list[tuple[int, int]] = []
    coding_position = 1

    def add_interval(fragment: _CdsFragment, length: int, reverse: bool) -> None:
        nonlocal coding_position
        for offset in range(length):
            genomic_offset = length - 1 - offset if reverse else offset
            layout.append((coding_position, fragment.start - 1 + genomic_offset))
            coding_position += 1

    # Translate each fragment's declared phase into the number of coding
    # bases missing from the 5' side of this fragment relative to codon
    # boundaries, then demand the assembled layout agrees.
    consumed = 0
    for fragment in ordered:
        if strand == "+":
            length = fragment.end - fragment.start + 1
            add_interval(fragment, length, reverse=False)
            expected_phase = (3 - (consumed % 3)) % 3
            if fragment.phase != expected_phase:
                raise _gff_error(
                    source,
                    fragment.line_number,
                    f"CDS phase {fragment.phase} for Parent {parent!r} contradicts "
                    f"the assembled reading frame (expected {expected_phase})",
                )
            consumed += length
        else:
            length = fragment.end - fragment.start + 1
            add_interval(fragment, length, reverse=True)
            # Phase counts bases missing at the fragment's 5' end, which on
            # the minus strand is its higher-coordinate edge: after reading
            # this (reversed) fragment the number of coding bases already
            # seen fixes the phase the next fragment must declare.
            expected_phase = (3 - (consumed % 3)) % 3
            if fragment.phase != expected_phase:
                raise _gff_error(
                    source,
                    fragment.line_number,
                    f"CDS phase {fragment.phase} for Parent {parent!r} contradicts "
                    f"the assembled reading frame (expected {expected_phase})",
                )
            consumed += length

    return _Transcript(
        parent=parent,
        strand=strand,
        sequence=first.seqid,
        sequence=tuple(layout),
    )


def _build_transcripts(
    fragments: dict[str, list[_CdsFragment]], source: str
) -> tuple[_Transcript, ...]:
    transcripts = [
        _build_layout(parent, parent_fragments, source)
        for parent, parent_fragments in fragments.items()
    ]
    transcripts.sort(key=lambda transcript: transcript.parent)
    return tuple(transcripts)


def _read_gff3(source: "str | os.PathLike[str] | io.TextIOBase") -> tuple[tuple[_Transcript, ...], str]:
    if isinstance(source, io.IOBase):
        stream: io.TextIOBase = source
        source_name = getattr(stream, "name", None)
        if not isinstance(source_name, str) or not source_name:
            source_name = "<stream>"
        close = False
    elif isinstance(source, (str, os.PathLike)):
        path = os.fspath(source)
        stream = open(path, "r", encoding="utf-8", newline="")
        source_name = path
        close = True
    else:
        raise TypeError("source must be a text path or a text stream")

    try:
        fragments = _parse_cds_fragments(stream, source_name)
        return _build_transcripts(fragments, source_name), source_name
    finally:
        if close:
            stream.close()


def _index_reference(
    reference: Iterable[SequenceRecord],
) -> dict[str, str]:
    sequences: dict[str, str] = {}
    for record in reference:
        sequences[record.identifier] = record.sequence
    return sequences


def _coding_base(transcript: _Transcript, chromosome: str, index: int) -> str:
    base = chromosome[index]
    if transcript.strand == "-":
        base = base.translate(_COMPLEMENT)
    return base


def _codons(
    transcript: _Transcript, chromosome: str
) -> list[tuple[int, tuple[int, ...], str]]:
    """Yield ``(codon_number, genomic_indices, codon_bases)`` per full codon."""
    codon_list: list[tuple[int, tuple[int, ...], str]] = []
    layout = transcript.layout
    for codon_number, start in enumerate(range(0, len(layout) - 2, 3), start=1):
        positions = layout[start : start + 3]
        indices = tuple(index for _coding_pos, index in positions)
        bases = "".join(_coding_base(transcript, chromosome, index) for index in indices)
        codon_list.append((codon_number, indices, bases))
    return codon_list


def _classify(
    codon_number: int, old_codon: str, new_codon: str
) -> tuple[str, str]:
    old_aa = _GENETIC_CODE[old_codon]
    new_aa = _GENETIC_CODE[new_codon]
    if codon_number == 1 and old_aa == "M" and new_aa != "M":
        consequence = "START_LOST"
    elif old_aa != "*" and new_aa == "*":
        consequence = "STOP_GAINED"
    elif old_aa == "*" and new_aa != "*":
        consequence = "STOP_LOST"
    elif old_aa == new_aa:
        consequence = "SYNONYMOUS"
    else:
        consequence = "MISSENSE"
    return consequence, _CONSEQUENCE_IMPACT[consequence]


def _is_snv(ref: str, alt: str) -> bool:
    return len(ref) == 1 and len(alt) == 1 and ref in "ACGT" and alt in "ACGT" and ref != alt


def _annotate_alt(
    record: VcfRecord,
    alt: str,
    transcripts: tuple[_Transcript, ...],
    sequences: dict[str, str],
) -> str:
    if not _is_snv(record.ref, alt):
        return f"{alt}|UNSUPPORTED|MODIFIER|.|.|.|."

    genomic_index = record.pos - 1
    hits: list[_Transcript] = [
        transcript
        for transcript in transcripts
        if transcript.sequence == record.chrom
        and any(index == genomic_index for _pos, index in transcript.layout)
    ]

    if not hits:
        return f"{alt}|NON_CODING|MODIFIER|.|.|.|."

    items: list[str] = []
    for transcript in hits:
        chromosome = sequences[record.chrom]
        for codon_number, indices, old_codon in _codons(transcript, chromosome):
            if genomic_index not in indices:
                continue
            position_in_codon = indices.index(genomic_index)
            alt_coding_base = (
                alt.translate(_COMPLEMENT) if transcript.strand == "-" else alt
            )
            new_bases = list(old_codon)
            new_bases[position_in_codon] = alt_coding_base
            new_codon = "".join(new_bases)

            layout = transcript.layout
            coding_positions = {
                index: coding_pos for coding_pos, index in layout
            }
            cds_pos = coding_positions[genomic_index]

            consequence, impact = _classify(codon_number, old_codon, new_codon)
            old_aa = _GENETIC_CODE[old_codon]
            new_aa = _GENETIC_CODE[new_codon]
            items.append(
                "|".join(
                    (
                        alt,
                        consequence,
                        impact,
                        transcript.parent,
                        str(cds_pos),
                        f"{old_codon}>{new_codon}",
                        f"{old_aa}>{new_aa}",
                    )
                )
            )
            break
    if not items:
        # The base belongs to the transcript's CDS span but fell outside a
        # complete codon (frame data inconsistent in length); treat the
        # coordinate as non-coding rather than guessing.
        return f"{alt}|NON_CODING|MODIFIER|.|.|.|."
    return ",".join(items)


def _info_keys(info: str) -> list[str]:
    keys: list[str] = []
    for item in info.split(";"):
        key = item.split("=", 1)[0]
        keys.append(key)
    return keys


def _check_existing_gvann(document: VcfFile) -> None:
    for line in document.header.meta_lines:
        if line.startswith(f"##{GVANN_ID}=") or line.startswith(
            f"##{GVANN_ID}<"
        ):
            raise AnnotationFormatError(
                f"{GVANN_ID} is already declared in the VCF header"
            )
    for record in document.records:
        if record.info and GVANN_ID in _info_keys(record.info):
            source = document.source
            location = (
                f"{source}:{record.line_number}: "
                if source and record.line_number
                else ""
            )
            raise AnnotationFormatError(
                f"{location}{GVANN_ID} is already present in a VCF record"
            )


_GVANN_HEADER = (
    '##INFO=<ID=GVANN,Number=.,Type=String,Description="Genome variant '
    'annotation: ALT|CONSEQUENCE|IMPACT|TRANSCRIPT|CDS_POS|CODON_CHANGE|'
    'AA_CHANGE; multiple transcripts are comma separated">'
)


def annotate_vcf(
    document: VcfFile,
    reference: "Mapping[str, str] | Iterable[SequenceRecord]",
    features: "str | os.PathLike[str] | io.TextIOBase | tuple[_Transcript, ...]",
) -> VcfFile:
    """Annotate every ALT allele of *document* with a ``GVANN`` INFO item.

    *reference* is a mapping of CHROM to upper-case sequence or an
    iterable of :class:`~genome_variant.sequence_io.SequenceRecord`;
    *features* is a GFF3 text path or text stream (CDS features define
    the annotated ranges, grouped into transcripts by ``Parent``).

    Record order, ALT order, sample columns and every existing field are
    preserved; only a single unique ``##INFO`` declaration for ``GVANN``
    is appended to the meta-information and a ``GVANN`` item is appended
    to the end of each record's INFO column (or starts the column when
    INFO was missing).  Consequences are ``START_LOST``, ``STOP_GAINED``,
    ``STOP_LOST``, ``SYNONYMOUS`` and ``MISSENSE`` for coding single-base
    ``A``/``C``/``G``/``T`` substitutions; SNVs outside every CDS get
    ``NON_CODING``/``MODIFIER`` and non-SNV, ambiguous or symbolic ALTs
    get ``UNSUPPORTED``/``MODIFIER``.

    Raises :class:`AnnotationFormatError` for malformed GFF3 data or a
    document that already declares or uses ``GVANN``, and
    :class:`~genome_variant.vcf.ReferenceMismatchError` when a coding
    record's CHROM is absent/duplicated in the reference or its REF does
    not match.
    """
    if isinstance(features, tuple):
        transcripts = features
    else:
        transcripts, _source_name = _read_gff3(features)

    _check_existing_gvann(document)

    if isinstance(reference, dict) or hasattr(reference, "keys"):
        sequences = dict(reference)
        duplicates: set[str] = set()
    else:
        sequences_map: dict[str, str] = {}
        duplicates = set()
        for record in reference:
            if record.identifier in sequences_map:
                duplicates.add(record.identifier)
            else:
                sequences_map[record.identifier] = record.sequence
        sequences = sequences_map

    from .vcf import ReferenceMismatchError

    annotated_records: list[VcfRecord] = []
    for record in document.records:
        # Reference validation follows normalize_vcf semantics for every
        # record so REF mismatches surface even outside CDS ranges.
        if record.chrom in duplicates:
            raise ReferenceMismatchError(
                f"CHROM {record.chrom} POS {record.pos}: CHROM occurs more than "
                "once in the reference"
            )
        try:
            chromosome = sequences[record.chrom]
        except KeyError:
            raise ReferenceMismatchError(
                f"CHROM {record.chrom} POS {record.pos}: no matching record in "
                "the reference"
            ) from None
        end = record.pos - 1 + len(record.ref)
        if record.pos < 1 or end > len(chromosome):
            from .vcf import VcfFormatError

            source = document.source
            location = (
                f"{source}:{record.line_number}: "
                if source and record.line_number
                else ""
            )
            raise VcfFormatError(
                f"{location}CHROM {record.chrom} POS {record.pos}: REF of length "
                f"{len(record.ref)} is out of bounds for a reference of length "
                f"{len(chromosome)}"
            )
        expected = chromosome[record.pos - 1 : end].upper()
        if expected != record.ref:
            raise ReferenceMismatchError(
                f"CHROM {record.chrom} POS {record.pos}: REF does not match the "
                f"reference: expected {expected!r}, found {record.ref!r}"
            )

        items = [
            _annotate_alt(record, alt, transcripts, sequences)
            for alt in record.alt
        ]
        gvann = f"{GVANN_ID}=" + ",".join(items)
        info = f"{record.info};{gvann}" if record.info else gvann
        annotated_records.append(replace(record, info=info))

    header = VcfHeader(
        meta_lines=document.header.meta_lines + (_GVANN_HEADER,),
        samples=document.header.samples,
    )
    return VcfFile(header, tuple(annotated_records), document.source)

